        case stills = "stills"
        case stillsInspected = "stills_inspected"
        case views = "views"
    }

    public init(coverageWords: String, depthSource: DepthSource, keyframes: Int, scanPoints: Int?, segments: [CaptureSegment]?, stills: Int, stillsInspected: Int, views: Views?) {
