// MARK: - CosmeticElement
public struct CosmeticElement: Codable, Sendable {
    /// Finding.category: defect (also when absent) = something looks broken, damaged or faulty;
    /// setup = a setup or assembly state, not a broken part: a battery missing or in backwards,
    /// a cable or connector unplugged or not fully in, a cover not clipped, a screw or fuse
    /// missing (repairos.vision.assembly). Code decides it from the state, never a model word.
    public let category: Category?
    public let confidenceWord: ConfidenceWord
    /// The photo and box the region was seen in. Absent for a row the design engine judged from
    /// the scan's measurements, not from a photo.
    public let crop: Crop?
    /// The crops of the other findings in a collapsed row (`crop` is the first).
    public let crops: [Crop]?
    public let evidence: [String]
    public let findingID: String
    /// A collapsed row: the findings of one physical issue (same still and overlapping crops, or
    /// the same place on the scan across stills) with the same issue, finding_id first. Each
    /// finding appears in no other row (MS1).
    public let findingIDS: [String]?
    /// For a setup finding: the plain fix a person can do, in one sentence (e.g. 'Put the
    /// batteries in, then test again.'). Shown to the user.
    public let fix: String?
    /// The fix for this row as data, so the app can show a card with a button instead of a
    /// sentence: what to do, what to buy, which file to print, or which meter check settles it.
    /// `fix` stays the same fix in one sentence. Absent when the design engine offered no fix
    /// for the row.
    public let fixPlan: FixPlan?
    /// Stages that looked at this region. A judged region always includes a state judge (vlm,
    /// classifier, meter or grain). grain: the design engine judged it against the product's own
    /// design (scan measurements, photos, readings).
    public let inspectedBy: [InspectedBy]
    /// none = a model looked and saw no issue. Every other value is Finding.state: a suspect.
    public let issue: Issue
    public let judgment: Judgment?
    public let location: Location
    /// Why the findings of a collapsed row are one issue.
    public let mergedBy: MergedBy?
    /// What the person said after trying the fix for this row (POST
    /// /v1/scans/{scan_id}/outcome). Set by the gateway when the report is read, never by the
    /// design engine; it is also the label the design engine learns from.
    public let outcome: Outcome?
    /// Generic class (vision/generic_classes.py), never a product name. For a row judged by the
    /// design engine: the design's own name for the part.
    public let partClass: String
    /// Plain words that let a person find the part in the photo.
    public let partWords: String?
    public let proof: Proof
    /// How many findings this collapsed row stands for.
    public let regions: Int?
    /// How much the issue matters (the vision model's word per crop; absent = not judged,
    /// treated as functional). Cosmetic issues are listed in `cosmetic`, never in `findings`.
    public let severity: Severity?
    public let subject: BottomNotPlacedSubject
    /// Findings of the same place on the scan that could not be judged in another photo
    /// (insufficient_evidence) and are judged in this row's photo instead, e.g. a closer photo
    /// added later to the same scan. They appear in no other row (MS1).
    public let supersededIDS: [String]?

    public enum CodingKeys: String, CodingKey {
        case category = "category"
        case confidenceWord = "confidence_word"
        case crop = "crop"
        case crops = "crops"
        case evidence = "evidence"
        case findingID = "finding_id"
        case findingIDS = "finding_ids"
        case fix = "fix"
        case fixPlan = "fix_plan"
        case inspectedBy = "inspected_by"
        case issue = "issue"
        case judgment = "judgment"
        case location = "location"
        case mergedBy = "merged_by"
        case outcome = "outcome"
        case partClass = "part_class"
        case partWords = "part_words"
        case proof = "proof"
        case regions = "regions"
        case severity = "severity"
        case subject = "subject"
        case supersededIDS = "superseded_ids"
    }

    public init(category: Category?, confidenceWord: ConfidenceWord, crop: Crop?, crops: [Crop]?, evidence: [String], findingID: String, findingIDS: [String]?, fix: String?, fixPlan: FixPlan?, inspectedBy: [InspectedBy], issue: Issue, judgment: Judgment?, location: Location, mergedBy: MergedBy?, outcome: Outcome?, partClass: String, partWords: String?, proof: Proof, regions: Int?, severity: Severity?, subject: BottomNotPlacedSubject, supersededIDS: [String]?) {
        self.category = category
        self.confidenceWord = confidenceWord
        self.crop = crop
        self.crops = crops
        self.evidence = evidence
        self.findingID = findingID
        self.findingIDS = findingIDS
        self.fix = fix
        self.fixPlan = fixPlan
        self.inspectedBy = inspectedBy
        self.issue = issue
        self.judgment = judgment
        self.location = location
        self.mergedBy = mergedBy
        self.outcome = outcome
        self.partClass = partClass
        self.partWords = partWords
        self.proof = proof
        self.regions = regions
        self.severity = severity
        self.subject = subject
        self.supersededIDS = supersededIDS
    }
}

