    /// Why, in plain words (no numbers; it is sent to the summary writer).
    public let text: String

    public enum CodingKeys: String, CodingKey {
        case caveat = "caveat"
        case code = "code"
        case rule = "rule"
        case text = "text"
    }

    public init(caveat: String?, code: VerdictReasonCode, rule: String, text: String) {
        self.caveat = caveat
        self.code = code
        self.rule = rule
