}

/// Output of a Mode A wide scan from the phone: a cropped point cloud in ARKit's world frame
/// plus keyframes with poses. The backend adds 'alignment' after ICP. Units are metres, Y up
/// (ARKit) unless a field name says otherwise. The design frame (the reference model) is
/// millimetres, Z up; alignment maps one to the other, including the Y-up -> Z-up turn.
// MARK: - ScanPackage
public struct ScanPackage: Codable, Sendable {
    /// Filled by the backend after ICP. Absent before alignment.
    public let alignment: Alignment?
    public let capturedAt: Date
    /// Fraction of visible voxels with >= 3 high-confidence hits (the on-phone heat map).
    public let coverageHint: Double?
    /// The AR box the user dragged; points outside were dropped. Points on or below the
    /// supporting plane + 5 mm were dropped too.
    public let cropBox: CropBox?
    /// Where the scan's geometry comes from. lidar (also when absent, as in every package before
    /// this field): ARKit sceneDepth fused into points_file. none: a no-LiDAR capture (A8):
    /// ARKit world-tracking poses and images only, so there is no points_file or point_count and
    /// nothing metric can be read off the scan itself.
    public let depthSource: DepthSource?
    public let device: Device
    /// Points and poses are in ARKit's world frame (metres, Y up). The design frame (mm, Z up)
    /// is reached via alignment.transform_arkit_world_to_design.
    public let frame: LocationFrame
    /// Unit vector pointing down in arkit_world (ARKit: [0,-1,0]).
    public let gravityArkitWorld: [Double]
    /// Kept frames only: tracking normal, sharp, no smudge. Selected every ~10 cm of travel or
    /// 15 deg of rotation.
    public let keyframes: [ScanPackageSchema]
    /// Optional triangle mesh of the same scene, binary little-endian PLY, arkit_world metres:
    /// float x, y, z (+ uchar red, green, blue) vertices and a face list. From backend TSDF
    /// fusion (an import, B12) or ARKit scene reconstruction (A2). Used to ray-cast close-up
    /// boxes onto the scan (repairos.locate).
    public let meshFile: String?
    public let pointCount: Int?
    /// Binary little-endian PLY, xyz float32 + rgb uint8, optional confidence/views uint8.
    public let pointsFile: String?
    /// Where keyframe poses and points_file come from. arkit (also when absent): ARKit world
    /// tracking, with points_file fused from sceneDepth into voxels (voxel_mm). object_tracked:
    /// the app's hand-held mode (the person turns or flips the object while the phone stays
    /// roughly still): the app tracks the object's 6-DoF pose and every pose and point is in the
    /// OBJECT frame, which is the ARKit world frame at the moment the object was locked (it
    /// rested on the support plane then; crop_box, support_plane and gravity_arkit_world
    /// describe that moment). Camera poses are the camera relative to the object, so they may
    /// lie below the support plane (the underside, seen after a flip) and the cloud includes the
    /// underside: never cut the cloud or the depth at the support plane for such a scan.
    /// Keyframes and stills carry pose_source and pose_quality; world-map relocalisation does
    /// not apply (the object moved), object-shape alignment does. photogrammetry: Apple
    /// PhotogrammetrySession (poses + pointCloud) run on the Object Capture images; poses and
    /// points share its gravity-aligned metric frame (metres, Y up, LiDAR-scaled when
    /// depth_source is lidar), and points_file is its point cloud, not voxel-fused, so there is
    /// no voxel_mm.
    public let poseSource: ScanPackagePoseSource?
    public let productID: String
    public let scanID: String
    /// Later capture segments of the same session: the object flipped for its underside (reason
    /// flipped, object_moved true: a quick mini-scan of the bottom in its own ARKit session;
    /// transform_to_segment0, from the phone's live alignment or the backend's registration,
    /// puts it on segment 0), or more photos of the same, unmoved object continued from the
    /// report (reason continued). Each has its own locked box and LiDAR cloud, in the same ARKit
    /// world frame as segment 0 unless aligned is false or object_moved is true.
    /// points_file/crop_box above are segment 0.
    public let segments: [ScanPackageSegment]?
    /// One repair session; groups scans, stills and readings.
    public let sessionID: String
    /// The table the object stood on (segment 0), as ARKit detected it: a horizontal plane
    /// anchor.
    public let supportPlane: SupportPlane?
    public let supportingPlaneRemoved: Bool?
    /// One line from the user. Goes into model state, never instructions (A9).
    public let symptom: String?
    public let units: Units
    /// Voxel pitch in millimetres when points_file is voxel-fused (3 default; 1-2 with PromptDA
    /// TSDF). Absent when the cloud keeps raw samples (the app's live LiDAR accumulation,
    /// photogrammetry).
    public let voxelMm: Double?

    public enum CodingKeys: String, CodingKey {
        case alignment = "alignment"
        case capturedAt = "captured_at"
        case coverageHint = "coverage_hint"
        case cropBox = "crop_box"
        case depthSource = "depth_source"
        case device = "device"
        case frame = "frame"
        case gravityArkitWorld = "gravity_arkit_world"
        case keyframes = "keyframes"
        case meshFile = "mesh_file"
        case pointCount = "point_count"
        case pointsFile = "points_file"
        case poseSource = "pose_source"
        case productID = "product_id"
        case scanID = "scan_id"
        case segments = "segments"
        case sessionID = "session_id"
        case supportPlane = "support_plane"
        case supportingPlaneRemoved = "supporting_plane_removed"
        case symptom = "symptom"
        case units = "units"
        case voxelMm = "voxel_mm"
    }

    public init(alignment: Alignment?, capturedAt: Date, coverageHint: Double?, cropBox: CropBox?, depthSource: DepthSource?, device: Device, frame: LocationFrame, gravityArkitWorld: [Double], keyframes: [ScanPackageSchema], meshFile: String?, pointCount: Int?, pointsFile: String?, poseSource: ScanPackagePoseSource?, productID: String, scanID: String, segments: [ScanPackageSegment]?, sessionID: String, supportPlane: SupportPlane?, supportingPlaneRemoved: Bool?, symptom: String?, units: Units, voxelMm: Double?) {
        self.alignment = alignment
        self.capturedAt = capturedAt
        self.coverageHint = coverageHint
        self.cropBox = cropBox
        self.depthSource = depthSource
        self.device = device
        self.frame = frame
        self.gravityArkitWorld = gravityArkitWorld
        self.keyframes = keyframes
        self.meshFile = meshFile
        self.pointCount = pointCount
        self.pointsFile = pointsFile
        self.poseSource = poseSource
        self.productID = productID
        self.scanID = scanID
        self.segments = segments
        self.sessionID = sessionID
        self.supportPlane = supportPlane
        self.supportingPlaneRemoved = supportingPlaneRemoved
        self.symptom = symptom
        self.units = units
        self.voxelMm = voxelMm
    }
}

/// Filled by the backend after ICP. Absent before alignment.
// MARK: - Alignment
public struct Alignment: Codable, Sendable {
    public let computedAt: Date
    /// The same cloud in the design frame's axes (Z up), written in design_points_units.
    public let designPointsFile: String?
    /// m: design axes in metres. mm: design-frame millimetres.
    public let designPointsUnits: DesignPointsUnits?
    /// Inlier fraction.
    public let fitness: Double
    /// False means no part verdicts are made from this scan (fit gate).
    public let gatePassed: Bool
    public let gateThresholdFitness: Double?
    /// e.g. open3d_robust_point_to_plane_icp
    public let method: String
    public let rmseMm: Double
    /// Row-major 4x4 mapping ARKit metres to design-frame millimetres: [p_design_mm, 1] = T *
