}

/// One Mode B close-up: a high-resolution still with its camera pose and the targets the
/// backend asked for. camera is in arkit_world (metres, Y up) from the phone; the backend
/// adds camera_design in the design frame (model.glb: millimetres, Z up) after alignment and
/// per-still re-registration. The backend projects each target into the still from
/// camera_design and the target's design-frame box.
// MARK: - Still
public struct Still: Codable, Sendable {
    /// For macro_detail: the guided target this detail belongs to.
    public let attachedToTargetID: String?
    /// True when the app took the shot because the ring filled, tracking was normal and
    /// sharpness was high.
    public let autoFired: Bool?
    /// Camera pose in arkit_world at capture (from the ARFrame returned with the still). For
    /// macro_detail this is the last AR pose and is approximate. May be absent only when
    /// pose_reliable is false: a plain photo has no pose, and none is made up.
    public let camera: StillCamera?
    /// Backend-filled pose in the design frame (mm, Z up) after alignment and depth
    /// re-registration.
    public let cameraDesign: CameraDesign?
    public let capturedAt: Date
    public let confidenceFile: String?
    /// Nearest ARKit depth frame (256x192) for re-registration.
    public let depthFile: String?
    /// Time between the still and the regular ARKit frame its depth_file came from (high-res
    /// frames carry no depth).
    public let depthGapMS: Int?
    /// Exposure duration of the still (ARKit camera).
    public let exposureS: Double?
    public let heightPx: Int
    /// JPEG (q >= 85). HEIC is converted on the phone.
    public let imageFile: String
    /// Pinhole intrinsics in pixels of the width_px x height_px image. May be absent only when
    /// pose_reliable is false and the focal length is unknown (a plain photo without EXIF focal
    /// length).
    public let intrinsics: StillIntrinsics?
    /// ISO of the still, from the frame's EXIF when ARKit gives it.
    public let iso: Double?
    /// guided: AR-ring target with pose. macro_detail: ultrawide macro outside the AR session,
    /// no reliable pose, evidence-only. label: product label for identification. unguided: a
    /// still taken without a target ring, e.g. a frame of an imported capture (B12) or a plain
    /// camera photo (tools/import_photos.py, pose_reliable false, no camera); targets is empty.
    public let kind: StillKind
    /// True when the app took the still in low light (it never blocks on light): judge dark
    /// detail with care.
    public let lowLight: Bool?
    /// The object tracker's confidence in camera, 0-1 (object_tracked only). Below 0.55 the app
    /// marks pose_reliable false; below 0.7 locate caps its confidence at medium.
    public let poseQuality: Double?
    /// False for macro_detail, when tracking was limited, or when the still has no pose at all
    /// (a plain photo: camera absent). Only when false may camera and intrinsics be absent.
    public let poseReliable: Bool?
    /// Where camera comes from. arkit (also when absent): ARKit world tracking. object_tracked:
    /// the app's hand-held mode: the camera relative to the tracked, moving object, in the
    /// scan's object frame (the ARKit world frame at the moment the object was locked; see
    /// scan-package pose_source).
    public let poseSource: KeyframePoseSource?
    /// The Mode A scan this still is registered to.
    public let scanID: String
    /// Capture segment (absent = 0). The app starts segment 1 after the person flips the object
    /// for the underside: the object moved, so poses from different segments are not in the same
    /// object frame. Stills of segment ≥ 1 are pose_reliable false until the segments are
    /// registered (on the Mac); their camera pose stays in the session's world frame.
    public let segment: Int?
    public let sessionID: String
    /// Laplacian variance.
    public let sharpness: Double?
    public let stillID: String
    /// What the backend asked this still to cover. Empty for a label still.
    public let targets: [TargetElement]
    /// Torch level during the still (0 = off); torch_on is level > 0.
    public let torchLevel: Double?
    public let torchOn: Bool?
    /// unknown: the capture app did not record it (an import); pose_reliable is then absent, or
    /// false when there is no pose at all (a plain photo).
    public let trackingState: TrackingState
    /// True when the user tapped 'skip, I can't reach it'. Targets then become not_inspected.
    public let userSkipped: Bool?
    /// The coverage-dome cell the still was taken from (app scan, e.g. r1s05: elevation ring 0-2
    /// above the support plane, azimuth sector 0-11 around the object; b1s05 is a view of the
    /// underside: in a hand-held scan, pose_source object_tracked, ring 1-2 below the object's
    /// middle in the object frame; in a flipped segment ("Scan the bottom"), ring and sector
    /// around the flipped object). Lets the backend see which sides were photographed.
    public let viewCell: String?
    public let widthPx: Int

    public enum CodingKeys: String, CodingKey {
        case attachedToTargetID = "attached_to_target_id"
        case autoFired = "auto_fired"
        case camera = "camera"
        case cameraDesign = "camera_design"
        case capturedAt = "captured_at"
        case confidenceFile = "confidence_file"
        case depthFile = "depth_file"
        case depthGapMS = "depth_gap_ms"
        case exposureS = "exposure_s"
        case heightPx = "height_px"
        case imageFile = "image_file"
        case intrinsics = "intrinsics"
        case iso = "iso"
        case kind = "kind"
        case lowLight = "low_light"
        case poseQuality = "pose_quality"
        case poseReliable = "pose_reliable"
        case poseSource = "pose_source"
        case scanID = "scan_id"
        case segment = "segment"
        case sessionID = "session_id"
        case sharpness = "sharpness"
        case stillID = "still_id"
        case targets = "targets"
        case torchLevel = "torch_level"
        case torchOn = "torch_on"
        case trackingState = "tracking_state"
        case userSkipped = "user_skipped"
        case viewCell = "view_cell"
        case widthPx = "width_px"
    }

    public init(attachedToTargetID: String?, autoFired: Bool?, camera: StillCamera?, cameraDesign: CameraDesign?, capturedAt: Date, confidenceFile: String?, depthFile: String?, depthGapMS: Int?, exposureS: Double?, heightPx: Int, imageFile: String, intrinsics: StillIntrinsics?, iso: Double?, kind: StillKind, lowLight: Bool?, poseQuality: Double?, poseReliable: Bool?, poseSource: KeyframePoseSource?, scanID: String, segment: Int?, sessionID: String, sharpness: Double?, stillID: String, targets: [TargetElement], torchLevel: Double?, torchOn: Bool?, trackingState: TrackingState, userSkipped: Bool?, viewCell: String?, widthPx: Int) {
        self.attachedToTargetID = attachedToTargetID
        self.autoFired = autoFired
        self.camera = camera
        self.cameraDesign = cameraDesign
        self.capturedAt = capturedAt
        self.confidenceFile = confidenceFile
        self.depthFile = depthFile
        self.depthGapMS = depthGapMS
        self.exposureS = exposureS
        self.heightPx = heightPx
        self.imageFile = imageFile
        self.intrinsics = intrinsics
        self.iso = iso
        self.kind = kind
        self.lowLight = lowLight
        self.poseQuality = poseQuality
        self.poseReliable = poseReliable
        self.poseSource = poseSource
        self.scanID = scanID
        self.segment = segment
        self.sessionID = sessionID
        self.sharpness = sharpness
        self.stillID = stillID
        self.targets = targets
        self.torchLevel = torchLevel
        self.torchOn = torchOn
        self.trackingState = trackingState
        self.userSkipped = userSkipped
        self.viewCell = viewCell
        self.widthPx = widthPx
    }
}

/// Camera pose in arkit_world at capture (from the ARFrame returned with the still). For
/// macro_detail this is the last AR pose and is approximate. May be absent only when
/// pose_reliable is false: a plain photo has no pose, and none is made up.
///
/// Camera-to-world pose in ARKit's world frame: metres, Y up. Camera axes as ARKit (x right,
/// y up, looking along -z).
// MARK: - StillCamera
public struct StillCamera: Codable, Sendable {
    public let frame: LocationFrame
    public let positionM: [Double]
    public let quaternionXyzw: [Double]

    public enum CodingKeys: String, CodingKey {
        case frame = "frame"
        case positionM = "position_m"
        case quaternionXyzw = "quaternion_xyzw"
    }

    public init(frame: LocationFrame, positionM: [Double], quaternionXyzw: [Double]) {
        self.frame = frame
        self.positionM = positionM
        self.quaternionXyzw = quaternionXyzw
    }
}

/// Backend-filled pose in the design frame (mm, Z up) after alignment and depth
/// re-registration.
///
/// Camera-to-design pose in the design frame (model.glb): millimetres, Z up. Same camera
/// axes as pose_arkit.
// MARK: - CameraDesign
public struct CameraDesign: Codable, Sendable {
    public let frame: CameraDesignFrame
    public let positionMm: [Double]
    public let quaternionXyzw: [Double]

    public enum CodingKeys: String, CodingKey {
        case frame = "frame"
        case positionMm = "position_mm"
        case quaternionXyzw = "quaternion_xyzw"
    }

    public init(frame: CameraDesignFrame, positionMm: [Double], quaternionXyzw: [Double]) {
        self.frame = frame
        self.positionMm = positionMm
        self.quaternionXyzw = quaternionXyzw
    }
}

public enum CameraDesignFrame: String, Codable, Sendable {
    case design = "design"
}

/// Pinhole intrinsics in pixels of the width_px x height_px image. May be absent only when
/// pose_reliable is false and the focal length is unknown (a plain photo without EXIF focal
/// length).
// MARK: - StillIntrinsics
public struct StillIntrinsics: Codable, Sendable {
    public let cx: Double
    public let cy: Double
    public let fx: Double
    public let fy: Double

    public enum CodingKeys: String, CodingKey {
        case cx = "cx"
        case cy = "cy"
        case fx = "fx"
        case fy = "fy"
    }

    public init(cx: Double, cy: Double, fx: Double, fy: Double) {
        self.cx = cx
        self.cy = cy
        self.fx = fx
        self.fy = fy
    }
}

/// guided: AR-ring target with pose. macro_detail: ultrawide macro outside the AR session,
/// no reliable pose, evidence-only. label: product label for identification. unguided: a
/// still taken without a target ring, e.g. a frame of an imported capture (B12) or a plain
/// camera photo (tools/import_photos.py, pose_reliable false, no camera); targets is empty.
public enum StillKind: String, Codable, Sendable {
    case guided = "guided"
    case label = "label"
    case macroDetail = "macro_detail"
    case unguided = "unguided"
}

// MARK: - TargetElement
public struct TargetElement: Codable, Sendable {
    /// The target's box in the design frame (mm, Z up), from the model.glb node bounds.
    /// Connector-level.
    public let boxMm: BoxMm?
    /// harness.csv wire names expected in view, e.g. WIRE_A.
    public let harnessRows: [String]?
    /// Part names (reference model nodes) expected in view, e.g. J1, LOAD1.
    public let partRefs: [String]?
    public let reason: TargetReason?
    public let targetID: String

    public enum CodingKeys: String, CodingKey {
        case boxMm = "box_mm"
        case harnessRows = "harness_rows"
        case partRefs = "part_refs"
        case reason = "reason"
        case targetID = "target_id"
    }

    public init(boxMm: BoxMm?, harnessRows: [String]?, partRefs: [String]?, reason: TargetReason?, targetID: String) {
        self.boxMm = boxMm
        self.harnessRows = harnessRows
        self.partRefs = partRefs
        self.reason = reason
        self.targetID = targetID
    }
}

/// The target's box in the design frame (mm, Z up), from the model.glb node bounds.
/// Connector-level.
// MARK: - BoxMm
public struct BoxMm: Codable, Sendable {
    public let max: [Double]
    public let min: [Double]

    public enum CodingKeys: String, CodingKey {
        case max = "max"
        case min = "min"
    }

    public init(max: [Double], min: [Double]) {
        self.max = max
        self.min = min
    }
}

public enum TargetReason: String, Codable, Sendable {
    case connector = "connector"
    case nonOkPart = "non_ok_part"
    case reshoot = "reshoot"
    case symptomPowerPath = "symptom_power_path"
    case userAdded = "user_added"
}

/// Fused judgement about one subject after Jev (or the rules fallback). Carries P(fault),
/// rank, fault kind and the verdict state. Probabilities are shown to users as words until
/// calibration_validated is true (I6).
// MARK: - Suspect
public struct Suspect: Codable, Sendable {
    /// True only after a reliability diagram on our labelled scans for this product class. Until
    /// then the UI shows p_fault_word only.
    public let calibrationValidated: Bool
    public let designTrust: DesignTrust?
    public let faultKind: FaultKind?
    /// Findings fused into this suspect.
    public let findingIDS: [String]
    public let fusionSource: Fusion
    /// e.g. jev-1.14.0.
    public let jevModel: String?
    public let onSymptomPowerPath: Bool?
    /// P(this subject is the cause or part of the cause of the symptom).
    public let pFault: Double
    /// Word shown to the user. Mapping from p_fault lives in code (policy.json).
    public let pFaultWord: Word
    /// MeterReading that confirmed or cleared this subject. Null while unproven.
    public let proofReadingID: String?
    /// 1 = top suspect.
    public let rank: Int
    public let scanID: String
    public let subject: SuspectSubject
    public let suspectID: String
    public let updatedAt: Date
    /// confirmed and cleared require a meter reading for electrical subjects (I2).
    public let verdict: JudgmentVerdict

    public enum CodingKeys: String, CodingKey {
        case calibrationValidated = "calibration_validated"
        case designTrust = "design_trust"
        case faultKind = "fault_kind"
        case findingIDS = "finding_ids"
        case fusionSource = "fusion_source"
        case jevModel = "jev_model"
        case onSymptomPowerPath = "on_symptom_power_path"
        case pFault = "p_fault"
        case pFaultWord = "p_fault_word"
        case proofReadingID = "proof_reading_id"
        case rank = "rank"
        case scanID = "scan_id"
        case subject = "subject"
        case suspectID = "suspect_id"
        case updatedAt = "updated_at"
        case verdict = "verdict"
    }

    public init(calibrationValidated: Bool, designTrust: DesignTrust?, faultKind: FaultKind?, findingIDS: [String], fusionSource: Fusion, jevModel: String?, onSymptomPowerPath: Bool?, pFault: Double, pFaultWord: Word, proofReadingID: String?, rank: Int, scanID: String, subject: SuspectSubject, suspectID: String, updatedAt: Date, verdict: JudgmentVerdict) {
        self.calibrationValidated = calibrationValidated
        self.designTrust = designTrust
        self.faultKind = faultKind
        self.findingIDS = findingIDS
        self.fusionSource = fusionSource
        self.jevModel = jevModel
        self.onSymptomPowerPath = onSymptomPowerPath
        self.pFault = pFault
        self.pFaultWord = pFaultWord
        self.proofReadingID = proofReadingID
        self.rank = rank
        self.scanID = scanID
        self.subject = subject
        self.suspectID = suspectID
        self.updatedAt = updatedAt
        self.verdict = verdict
    }
}

// MARK: - FaultKind
public struct FaultKind: Codable, Sendable {
    public let choice: String
    /// Seed used to shuffle options (Jev leans to the first option).
    public let optionOrderSeed: Int?
    /// Option -> probability. Options for a wire: unplugged, wrong_pin_or_colour_order,
    /// broken_or_missing, damaged_insulation, ok, not_enough_evidence.
    public let probabilities: [String: Double]

    public enum CodingKeys: String, CodingKey {
        case choice = "choice"
        case optionOrderSeed = "option_order_seed"
        case probabilities = "probabilities"
    }

    public init(choice: String, optionOrderSeed: Int?, probabilities: [String: Double]) {
        self.choice = choice
        self.optionOrderSeed = optionOrderSeed
        self.probabilities = probabilities
    }
}

/// Same as Finding.subject: ref is the part name (reference model node), harness wire name
/// or net name.
// MARK: - SuspectSubject
public struct SuspectSubject: Codable, Sendable {
    public let kind: SubjectKind
    public let pins: [String]?
    public let ref: String

    public enum CodingKeys: String, CodingKey {
        case kind = "kind"
        case pins = "pins"
        case ref = "ref"
    }

    public init(kind: SubjectKind, pins: [String]?, ref: String) {
        self.kind = kind
        self.pins = pins
        self.ref = ref
    }
}
